7	 * formatted {@code <REGION><FY><HASH8><CHK>} (no separators, e.g. {@code NSW261A2B3C4D5}):
8	 *
9	 * <ul>
10	 *   <li>REGION &mdash; the region code derived from the owner's postcode (falling back to its city,
11	 *       else {@link CityRegion#UNKNOWN}).</li>
12	 *   <li>FY &mdash; the two-digit fiscal year (starting 1 July) of the business-day-adjusted
13	 *       registration date (see {@link FiscalYear}).</li>
14	 *   <li>HASH8 &mdash; the first 8 upper-case hex characters of SHA-256 over the normalized telephone
15	 *       followed by the last name (the same hash used by the region-and-hash identity).</li>
16	 *   <li>CHK &mdash; a single {@link Luhn} check digit computed over the digits of
17	 *       {@code <REGION><FY><HASH8>}, guarding against transcription errors of the id.</li>
18	 * </ul>
19	 *
20	 * <p>The owner's {@link Owner#getLocality() locality} is the REGION read back out of it.
21	 */
22	public final class MemberId {
23	
24	    /** Number of leading hex characters of the hash kept in the id. */
25	    private static final int HASH_LENGTH = 8;
26	
27	    /** Fixed-width tail after REGION: FY (2) + HASH8 (8) + CHK (1). */
28	    private static final int TAIL_LENGTH = 2 + HASH_LENGTH + 1;
29	
30	    private MemberId() {
31	    }
32	
33	    /**
34	     * The member id for an owner in {@code region}, registered in fiscal year {@code fiscalYearTwoDigit}
35	     * (00&ndash;99), whose normalized telephone and last name are {@code telephone} and {@code lastName}.
36	     */
37	    public static String of(String region, int fiscalYearTwoDigit, String telephone, String lastName) {
38	        String hash8 = Sha256.hex(telephone + lastName).substring(0, HASH_LENGTH);
39	        String body = String.format("%s%02d%s", region, fiscalYearTwoDigit, hash8);
40	        return body + Luhn.checkDigit(body);
41	    }
42	
43	    /**
44	     * A unique variant of {@code base}: {@code base} itself when {@code taken} reports it free,
45	     * otherwise {@code base-<n>} with the smallest {@code n >= 2} that {@code taken} reports free.
46	     * Used to de-duplicate a derived id against the ids already in use.
47	     */
48	    public static String deduplicate(String base, Predicate<String> taken) {
49	        if (!taken.test(base)) {
50	            return base;
51	        }
52	        for (int n = 2; ; n++) {
53	            String candidate = base + "-" + n;
54	            if (!taken.test(candidate)) {
55	                return candidate;
56	            }
57	        }
58	    }
