360	    /**
361	     * The owner's identity key: the single derived value all duplicate detection is expressed
362	     * through, the lower-case SHA-256 hex digest of
363	     * {@code <normalizedTelephone>|<lowerEmail>|<soundex(lastName)>}. Two owners are duplicates only
364	     * when their whole identity keys are equal, so household members (same last name and postcode)
365	     * with different telephones have different keys and are not hard duplicates.
366	     */
367	    @Transient
368	    public String getIdentityKey() {
369	        String raw = blankToEmpty(this.telephone) + '|'
370	                + blankToEmpty(this.email).toLowerCase(Locale.ROOT) + '|'
371	                + Soundex.encode(this.getLastName());
372	        return Sha256.lowerHex(raw);
373	    }
374	
375	    private static String blankToEmpty(String value) {
376	        return (value == null) ? "" : value;
377	    }
