391	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
392	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
393	        return Collections.unmodifiableList(sortedPets);
394	    }
