416	     * Return the Pet with the given name, or null if none found for this Owner.
417	     *
418	     * @param name to test
419	     * @return true if pet name is already in use
420	     */
421	    public Pet getPet(String name, boolean ignoreNew) {
422	        name = name.toLowerCase();
423	        for (Pet pet : getPetsInternal()) {
424	            if (!ignoreNew || !pet.isNew()) {
425	                String compName = pet.getName();
426	                compName = compName.toLowerCase();
427	                if (compName.equals(name)) {
428	                    return pet;
429	                }
430	            }
431	        }
432	        return null;
433	    }
434	
435	    public Pet getPet(Integer petId) {
436	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
437	    }
438	
439	    @Override
440	    public String toString() {
441	        return new ToStringCreator(this)
442	
443	            .append("id", this.getId())
444	            .append("new", this.isNew())
445	            .append("lastName", this.getLastName())
446	            .append("firstName", this.getFirstName())
447	            .append("address", this.address)
448	            .append("city", this.city)
449	            .append("telephone", this.telephone)
450	            .toString();
451	    }
452	}
